def voce_mappa(k):
    tit,rami=MAPPE[k]
    out=["Mappa dell'argomento: %s."%tit.lower() if not k.startswith('CMF') else "Mappa riassuntiva: %s."%tit.lower()]
    for i,(c,p,e,es) in enumerate(rami):
        out.append("%s ramo: %s. Parola chiave: %s. Per esempio, %s."%(ORD[i],c[0].lower()+c[1:],p.lower(),es or e[0].lower()+e[1:]))
    return out

